import React from 'react';
import { useNavigate } from 'react-router-dom';
import './ChooseRole.css';

function ChooseRole() {
  const navigate = useNavigate();

  return (
    <div className="choose-role-page">
      <div className="choose-role-container">
        <h1>TENTUKAN PERANMU</h1>
        <p className="subtitle">Kamu mau ngapain?</p>
        <p className="description">Pilih peran Anda sekarang. Anda selalu bisa berpindah peran nanti di menu profil dengan satu klik mudah.</p>
        <div className="role-options">
          <div className="role-card" onClick={() => navigate('/dashboard-customer')}>
            <div className="role-icon">👤</div>
            <h3>Saya membutuhkan pekerja (Customer)</h3>
            <p>Cari talenta lepas profesional secara instan untuk membantu bisnis Anda.</p>
          </div>
          <div className="role-card" onClick={() => navigate('/dashboard-worker')}>
            <div className="role-icon">💼</div>
            <h3>Saya ingin bekerja</h3>
            <p>Temukan job instan yang sesuai keahlianmu dan langsung dapatkan bayaran.</p>
          </div>
        </div>
        <button className="btn-continue" onClick={() => navigate('/dashboard-customer')}>Lanjutkan</button>
      </div>
    </div>
  );
}

export default ChooseRole;
